/**
 * Catalog contracts: works, editions, copies and locations.
 *
 * Common rules:
 * - IDs are UUIDv7 and may be generated by the client (optional on creation).
 * - Every entity has a `version`; updates send `baseVersion` (the version the client saw).
 *   If another device changed the SAME fields afterwards the server answers 409 with the conflicts;
 *   if it changed other fields, the changes are merged without losing anything.
 * - Validation messages are i18n keys (see i18n.ts), never translated text.
 */
import { z } from 'zod';
import { normalizeIsbn } from './isbn.js';
import { SHA256_RE, UUID_RE } from './ids.js';

export const Id = z.string().regex(UUID_RE, 'validation.invalidId');
export const AssetId = z.string().regex(SHA256_RE, 'validation.invalidAssetId');
const text = (max: number) => z.string().trim().max(max);
const optText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .nullish()
    .transform((v) => (v ? v : null));
const nameList = z
  .array(z.string().trim().min(1).max(200))
  .max(30)
  .transform((a) => [...new Set(a)]);
const IsoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'validation.invalidDate');

/** Optional ISBN: normalised to ISBN-13; invalid codes fail with an `isbn.<reason>` key. */
export const IsbnField = z
  .string()
  .nullish()
  .transform((v, ctx) => {
    if (!v || !v.trim()) return null;
    const r = normalizeIsbn(v);
    if (!r.ok) {
      ctx.addIssue({ code: 'custom', message: `isbn.${r.reason}` });
      return z.NEVER;
    }
    return r.isbn13;
  });

// ---------- Enumerations (labels live in i18n.ts) ----------
export const LOCATION_KINDS = ['home', 'room', 'bookcase', 'shelf', 'box', 'other'] as const;
export const LocationKind = z.enum(LOCATION_KINDS);
export type LocationKind = z.infer<typeof LocationKind>;

export const CONDITIONS = ['new', 'fine', 'good', 'used', 'fair', 'poor'] as const;
export const Condition = z.enum(CONDITIONS);
export type Condition = z.infer<typeof Condition>;

export const RETIRE_REASONS = ['gifted', 'sold', 'lost', 'damaged', 'other'] as const;
export const RetireReason = z.enum(RETIRE_REASONS);
export type RetireReason = z.infer<typeof RetireReason>;

export const MetadataStatus = z.enum(['complete', 'provisional']);

/** Reading of one copy (design §4, BR11–BR13). "pending" is also what a work without sessions is. */
export const READING_STATUSES = ['pending', 'reading', 'read', 'abandoned'] as const;
export const ReadingStatus = z.enum(READING_STATUSES);
export type ReadingStatus = z.infer<typeof ReadingStatus>;

// ---------- Editable fields ----------
export const WorkFields = z.object({
  title: text(500).min(1, 'validation.titleRequired'),
  subtitle: optText(500),
  authors: nameList.default([]),
  subjects: nameList.default([]),
  description: optText(10_000),
  originalTitle: optText(500),
  originalLanguage: optText(8),
  series: optText(200),
  seriesIndex: z.number().min(0).max(100_000).nullish().default(null),
});
export type WorkFields = z.infer<typeof WorkFields>;

export const EditionFields = z.object({
  /** Only when the edition's title differs from the work's (e.g. a translation). */
  title: optText(500),
  subtitle: optText(500),
  publisher: optText(200),
  publishedYear: z.number().int().min(0).max(2100).nullish().default(null),
  language: optText(8),
  pages: z.number().int().min(1).max(100_000).nullish().default(null),
  format: optText(100),
  isbn13: IsbnField.default(null),
  coverAssetId: AssetId.nullish().default(null),
  metadataStatus: MetadataStatus.default('complete'),
  metadataSource: optText(100),
});
export type EditionFields = z.infer<typeof EditionFields>;

export const CopyFields = z.object({
  locationId: Id.nullish().default(null),
  condition: Condition.default('good'),
  acquiredOn: IsoDate.nullish().default(null),
  /** Price in cents to avoid floating point. */
  priceCents: z.number().int().min(0).max(100_000_000).nullish().default(null),
  priceCurrency: z
    .string()
    .regex(/^[A-Z]{3}$/)
    .default('EUR'),
  notes: text(5000).default(''),
});
export type CopyFields = z.infer<typeof CopyFields>;

/**
 * A reading session. Moving to `reading` without a start date sets it to today; moving to `read`
 * without an end date sets that one (BR11). Rating goes from 0.5 to 5 in half points.
 */
export const ReadingFields = z.object({
  status: ReadingStatus,
  startedOn: IsoDate.nullish().default(null),
  finishedOn: IsoDate.nullish().default(null),
  rating: z.number().min(0.5).max(5).multipleOf(0.5).nullish().default(null),
  notes: text(5000).default(''),
});
export type ReadingFields = z.infer<typeof ReadingFields>;

/**
 * A wish (design §4, BR14–BR15): never part of the collection. "I bought it" creates the copy (and the
 * edition/work if missing) and then sets `status: acquired` with `acquiredCopyId`; the wish is kept.
 */
export const WISH_PRIORITIES = ['low', 'normal', 'high'] as const;
export const WISH_STATUSES = ['open', 'acquired', 'discarded'] as const;
export const WishFields = z.object({
  title: text(500).min(1, 'validation.titleRequired'),
  authors: nameList.default([]),
  isbn13: IsbnField.default(null),
  /** Optional link to something you already own (another edition of a work, for instance). */
  workId: Id.nullish().default(null),
  priority: z.enum(WISH_PRIORITIES).default('normal'),
  notes: text(5000).default(''),
  status: z.enum(WISH_STATUSES).default('open'),
  acquiredCopyId: Id.nullish().default(null),
});
export type WishFields = z.infer<typeof WishFields>;

// ---------- Creation ----------
/** Full creation in one operation: new or existing work + edition + first copy. */
export const BookCreate = z
  .object({
    workId: Id.optional(),
    work: WorkFields.extend({ id: Id.optional() }).optional(),
    edition: EditionFields.extend({ id: Id.optional() }),
    copy: CopyFields.extend({ id: Id.optional() }),
    /** Explicit confirmation to create an edition whose ISBN already exists. */
    allowDuplicateIsbn: z.boolean().default(false),
  })
  .refine((b) => !!b.workId !== !!b.work, {
    message: 'validation.workOrWorkId',
  });
export type BookCreate = z.input<typeof BookCreate>;

export const CopyCreate = CopyFields.extend({ id: Id.optional(), editionId: Id });
export type CopyCreate = z.input<typeof CopyCreate>;

export const ReadingCreate = ReadingFields.extend({ id: Id.optional(), copyId: Id });
export type ReadingCreate = z.input<typeof ReadingCreate>;

export const WishCreate = WishFields.extend({ id: Id.optional() });
export type WishCreate = z.input<typeof WishCreate>;

export const LocationCreate = z.object({
  id: Id.optional(),
  parentId: Id.nullable(),
  name: text(80).min(1, 'validation.nameRequired'),
  kind: LocationKind.default('other'),
  sortOrder: z.number().int().default(0),
});
export type LocationCreate = z.input<typeof LocationCreate>;

// ---------- Updates (partial, with base version) ----------
/**
 * Partial update schema. CAREFUL: in Zod 4 `.partial()` still applies `.default()` values,
 * so a single-field PATCH would "reset" every other field. That is why defaults are stripped here.
 */
type NoDefault<S> = S extends z.ZodDefault<infer I> ? I : S;
const patchOf = <T extends z.ZodRawShape>(fields: z.ZodObject<T>) => {
  const shape = Object.fromEntries(
    Object.entries(fields.shape).map(([k, v]) => [
      k,
      (v instanceof z.ZodDefault ? (v.unwrap() as z.ZodType) : (v as z.ZodType)).optional(),
    ]),
  ) as { [K in keyof T]: z.ZodOptional<NoDefault<T[K]> & z.ZodType> };
  return z.object({ baseVersion: z.number().int().min(1), fields: z.object(shape) });
};

export const WorkPatch = patchOf(WorkFields);
export const EditionPatch = patchOf(EditionFields);
export const CopyPatch = patchOf(
  CopyFields.extend({
    status: z.enum(['active', 'retired']),
    retiredReason: RetireReason.nullable(),
  }),
);
export const LocationPatch = patchOf(
  z.object({
    parentId: Id.nullable(),
    name: text(80).min(1, 'validation.nameRequired'),
    kind: LocationKind,
    sortOrder: z.number().int(),
  }),
);
export const ReadingPatch = patchOf(ReadingFields);
export type ReadingPatch = z.input<typeof ReadingPatch>;
export const WishPatch = patchOf(WishFields);
export type WishPatch = z.input<typeof WishPatch>;
export type WorkPatch = z.input<typeof WorkPatch>;
export type EditionPatch = z.input<typeof EditionPatch>;
export type CopyPatch = z.input<typeof CopyPatch>;
export type LocationPatch = z.input<typeof LocationPatch>;

// ---------- Responses ----------
type Versioned = { id: string; version: number; createdAt: string; updatedAt: string };
export type WorkDTO = Versioned & z.infer<typeof WorkFields>;
export type EditionDTO = Versioned &
  z.infer<typeof EditionFields> & { workId: string; isbn10: string | null };
export type CopyDTO = Versioned &
  z.infer<typeof CopyFields> & {
    editionId: string;
    code: string;
    status: 'active' | 'retired';
    retiredReason: string | null;
    retiredOn: string | null;
    locationPath: string[];
  };
export type LocationDTO = Versioned & {
  parentId: string | null;
  name: string;
  kind: LocationKind;
  sortOrder: number;
  /** Copies in this location and all its sub-locations. */
  copyCount: number;
  /** Copies placed directly here. */
  directCount: number;
};
export type LocationTree = { items: LocationDTO[]; unassigned: number };

export type ReadingDTO = Versioned & ReadingFields & { copyId: string };
export type WishDTO = Versioned & WishFields;
export type WishList = { items: WishDTO[] };

export type WorkDetail = {
  work: WorkDTO;
  editions: (EditionDTO & { copies: CopyDTO[] })[];
  /** Every reading session of any copy of the work, oldest first. */
  readings: ReadingDTO[];
  /** Derived (BR13): reading if a session is active, read if any finished, otherwise pending. */
  readingStatus: 'pending' | 'reading' | 'read';
};

/** BR13, shared by the server and the web (Android ports it). */
export function workReadingStatus(sessions: { status: ReadingStatus }[]): WorkDetail['readingStatus'] {
  if (sessions.some((s) => s.status === 'reading')) return 'reading';
  if (sessions.some((s) => s.status === 'read')) return 'read';
  return 'pending';
}

export const LIBRARY_SORTS = ['title', 'author', 'acquired', 'location', 'added'] as const;
export const LibraryQuery = z.object({
  q: z.string().trim().max(200).optional(),
  /** Location id (sub-locations included) or "none" for copies without a location. */
  location: z.union([Id, z.literal('none')]).optional(),
  subject: z.string().max(200).optional(),
  language: z.string().max(8).optional(),
  sort: z.enum(LIBRARY_SORTS).default('title'),
  limit: z.coerce.number().int().min(1).max(500).default(100),
  offset: z.coerce.number().int().min(0).default(0),
});
export type LibraryQuery = z.input<typeof LibraryQuery>;

export type LibraryItem = {
  editionId: string;
  workId: string;
  title: string;
  subtitle: string | null;
  authors: string[];
  subjects: string[];
  publisher: string | null;
  publishedYear: number | null;
  language: string | null;
  isbn13: string | null;
  coverAssetId: string | null;
  metadataStatus: 'complete' | 'provisional';
  editionCount: number;
  copies: { id: string; code: string; locationId: string | null; locationPath: string[] }[];
  lastAcquiredOn: string | null;
};
export type LibraryPage = { items: LibraryItem[]; total: number; tookMs: number };
export type LibraryFacets = { subjects: { name: string; count: number }[]; languages: string[] };

// ---------- External metadata ----------
export type MetadataProposal = {
  title: string | null;
  subtitle: string | null;
  authors: string[];
  publisher: string | null;
  publishedYear: number | null;
  language: string | null;
  pages: number | null;
  subjects: string[];
  description: string | null;
  coverUrl: string | null;
};
export type LookupResult = {
  isbn13: string;
  isbn10: string | null;
  found: boolean;
  sources: string[];
  proposal: MetadataProposal | null;
  /** Set when you already own this edition: offer "add another copy" instead of duplicating it. */
  existing: { editionId: string; workId: string; title: string; copies: number } | null;
  /** Providers that failed (offline, timeout…): adding the book manually is still possible. */
  errors: string[];
};

export const FetchAssetRequest = z.object({ url: z.url() });
export type AssetDTO = { id: string; mime: string; width: number; height: number; bytes: number };

export type ConflictProblem = {
  currentVersion: number;
  conflicts: { field: string; current: unknown; yours: unknown }[];
};
